#include <vector>
#include <complex>
#include <cmath>

typedef std::complex<double> dcomp;

std::vector<dcomp> calculate_mode_annihilation_diagonal(size_t cutoff) {
    std::vector<dcomp> diagonal;
    diagonal.reserve(cutoff - 1);
    for (size_t n = 0; n < cutoff - 1; ++n) {
        diagonal.push_back(std::sqrt(static_cast<double>(n + 1)));
    }
    return diagonal;
}

